<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class CareerOpportunityController extends Controller
{
 private function schoolId(): int { return (int) session('school_id', 1); }
 public function dashboard() { $q=DB::table('career_opportunities')->where('school_id',$this->schoolId()); return view('career.dashboard',['total'=>(clone $q)->count(),'active'=>(clone $q)->where('status','open')->count(),'recent'=>(clone $q)->latest()->limit(6)->get()]); }
 public function index(Request $request) { $q=DB::table('career_opportunities')->where('school_id',$this->schoolId()); if($request->filled('search')) $q->where(function($x) use($request) { $x->where('title','like','%'.$request->search.'%'); }); if($request->filled('status')) $q->where('status',$request->status); $items=$q->latest()->paginate(15)->withQueryString(); return view('career.index',compact('items')); }
 public function create() { $campuses=DB::table('campuses')->where('school_id',$this->schoolId())->orderBy('name')->get(); $staff=DB::table('staff_profiles')->where('school_id',$this->schoolId())->whereNull('deleted_at')->orderBy('first_name')->get(); return view('career.create',compact('campuses','staff')); }
 public function store(Request $request) { $data=$request->validate(['title'=>'required|string|max:255','organization'=>'required|string|max:255','opportunity_type'=>'required|in:job,internship,scholarship,training','description'=>'nullable|string','location'=>'nullable|string|max:255','stipend_or_salary'=>'nullable|numeric|min:0','application_deadline'=>'nullable|date','eligibility'=>'nullable|string|max:255','status'=>'required|in:open,closed,draft','campus_id'=>'nullable|integer']); $data['school_id']=$schoolId; DB::table('career_opportunities')->insert($data+['created_at'=>now(),'updated_at'=>now()]); return redirect()->route('career.index')->with('success','Record created successfully.'); }
 public function show(int $id) { $item=DB::table('career_opportunities')->where('school_id',$this->schoolId())->find($id); abort_unless($item,404); return view('career.show',compact('item')); }
 public function edit(int $id) { $item=DB::table('career_opportunities')->where('school_id',$this->schoolId())->find($id); abort_unless($item,404); $campuses=DB::table('campuses')->where('school_id',$this->schoolId())->orderBy('name')->get(); $staff=DB::table('staff_profiles')->where('school_id',$this->schoolId())->whereNull('deleted_at')->orderBy('first_name')->get(); return view('career.edit',compact('item','campuses','staff')); }
 public function update(Request $request,int $id) { $item=DB::table('career_opportunities')->where('school_id',$this->schoolId())->find($id); abort_unless($item,404); $data=$request->validate(['title'=>'required|string|max:255','organization'=>'required|string|max:255','opportunity_type'=>'required|in:job,internship,scholarship,training','description'=>'nullable|string','location'=>'nullable|string|max:255','stipend_or_salary'=>'nullable|numeric|min:0','application_deadline'=>'nullable|date','eligibility'=>'nullable|string|max:255','status'=>'required|in:open,closed,draft','campus_id'=>'nullable|integer']); $data['school_id']=$schoolId; $data['updated_at']=now(); DB::table('career_opportunities')->where('id',$id)->where('school_id',$this->schoolId())->update($data); return redirect()->route('career.show',$id)->with('success','Record updated successfully.'); }
 public function destroy(int $id) { $deleted=DB::table('career_opportunities')->where('school_id',$this->schoolId())->where('id',$id)->delete(); abort_unless($deleted,404); return redirect()->route('career.index')->with('success','Record deleted successfully.'); }
}
